const cfg = $('Settings').first().json;
if (!cfg.accountUid || cfg.accountUid.startsWith('YOUR_') || !cfg.folderUid || cfg.folderUid.startsWith('YOUR_')) {
  throw new Error('Open Settings and replace the Folderit accountUid and folderUid placeholders.');
}
const allowed = String(cfg.allowedExtensions || '').split(',').map(v => v.trim().toLowerCase().replace(/^\./, '')).filter(Boolean);
if (!allowed.length) throw new Error('Set allowedExtensions, for example pdf,docx,txt.');
const emails = $('New email with attachments').all();
const out = [];
for (let i = 0; i < emails.length; i++) {
  const mail = emails[i];
  for (const [field, binary] of Object.entries(mail.binary || {})) {
    if (!field.startsWith('attachment_')) continue;
    const fileName = String(binary.fileName || '').split(/[\\/]/).pop().replace(/[\x00-\x1f\x7f]/g, '').trim();
    const extension = fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '';
    if (!fileName || !allowed.includes(extension)) continue;
    out.push({json: {fileName, sourceAttachment: field, messageId: String(mail.json.messageId || mail.json.uid || ''), accountUid: cfg.accountUid, folderUid: cfg.folderUid}, binary: {data: {...binary, fileName}}, pairedItem: {item: 0}});
  }
}
return out;

return $input.all().map((item, i) => {
  const expected = $('Split and validate attachments').all()[i].json;
  if (!item.json.uid || item.json.name !== expected.fileName || item.json.folderUid !== expected.folderUid) {
    throw new Error('Upload readback did not match the attachment. Inspect Folderit before retrying.');
  }
  return {json: {archived: true, uid: item.json.uid, name: item.json.name, folderUid: item.json.folderUid, messageId: expected.messageId, sourceAttachment: expected.sourceAttachment}, pairedItem: {item: i}};
});
